// Ported from the Node app's Sequelize model VehicleLocation (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class VehicleLocationConfiguration : IEntityTypeConfiguration<VehicleLocation>
{
    public void Configure(EntityTypeBuilder<VehicleLocation> builder)
    {
        builder.ToTable("vehicle_locations");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.VehicleId).HasColumnName("vehicle_id");
        builder.Property(e => e.Latitude).HasColumnName("latitude").HasColumnType("decimal(9,6)");
        builder.Property(e => e.Longitude).HasColumnName("longitude").HasColumnType("decimal(9,6)");
        builder.Property(e => e.Speed).HasColumnName("speed").HasColumnType("decimal(5,1)");
        builder.Property(e => e.RecordedAt).HasColumnName("recorded_at").HasColumnType("datetime2");
        builder.HasIndex(e => new { e.VehicleId, e.RecordedAt }).HasDatabaseName("ix_vloc");
        builder.HasOne(e => e.Vehicle).WithMany(p => p.VehicleLocations).HasForeignKey(e => e.VehicleId).OnDelete(DeleteBehavior.NoAction);
    }
}
